<script setup lang="ts">
const {feedbackTarget,captureAction}=useActionFeedback()
const props=defineProps<{game:any;initialSection?:string}>(),emit=defineEmits(['changed','processing'])
const navigationNews=useNavigationNews()
const data=ref<any>(null),busy=ref(false),error=ref(''),notice=ref(''),review=ref<any>(null),mode=ref(['headquarters','catalog','inventory'].includes(props.initialSection||'')?props.initialSection!:'headquarters'),category=ref(''),quantity=ref(1)
const commands=useState<Record<string,any>>('logistics-commands',()=>({})),pending=computed({get:()=>commands.value[props.game.id]??null,set:(v:any)=>commands.value={...commands.value,[props.game.id]:v}}),locked=computed(()=>busy.value||!!pending.value)
const base=()=>'/api/v1/games/'+props.game.id,money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(n/100)
const categories:any={combat:'Combate',recon:'Reconhecimento',medical:'Médico',technical:'Técnico',communication:'Comunicação',logistics:'Logístico'},states:any={in_delivery:'Em entrega',available:'No depósito',reserved:'Reservado',in_use:'Em missão',maintenance:'Em preparação',destroyed:'Destruído'},capacities:any={training:'vagas de treinamento',infirmary:'vagas de tratamento',depot:'unidades de armazenagem',operations:'operações simultâneas',administration:'operadores com vínculo'}
const qualityChoice=ref<Record<string,string>>({})
const catalogGroups=computed(()=>kitCatalogGroups(data.value?.catalog??[],category.value))
function activeKit(group:any){return group.variants.find((c:any)=>c.id===qualityChoice.value[group.category])??group.variants[0]}
function selectQuality(category:string,id:string){qualityChoice.value={...qualityChoice.value,[category]:id};review.value=null}
function purchaseIssue(c:any){return kitPurchaseIssue(c,quantity.value,data.value,props.game.cashCents)}
function upgradeProgress(m:any){return Math.max(0,Math.min(m.upgradeTurns,m.upgradeTurns-(m.dueTurn-data.value.currentTurn)))}
async function refresh(){try{data.value=await $fetch(base()+'/logistics');navigationNews.markRead(props.game.id,'infrastructure.'+mode.value);return true}catch(e:any){error.value=e.data?.message||'Não foi possível carregar a sede.';return false}}
const scheduled=(target:string)=>(data.value?.pendingOrders??[]).filter((o:any)=>o.target===target&&o.kind!=='purchase')
const purchases=(catalogId:string)=>(data.value?.pendingOrders??[]).filter((o:any)=>o.kind==='purchase'&&o.command.catalogId===catalogId)
function cancelQueued(id:string){review.value={path:'/orders/'+id+'/cancel',body:{}};return run()}
function prepare(path:string,body:any,label:string,cost:number,consequence:string){review.value={path,body,label,cost,consequence};error.value=''}
async function run(){if(busy.value||(!review.value&&!pending.value))return;const command=pending.value||{path:review.value.path,body:{...review.value.body,requestId:crypto.randomUUID(),expectedVersion:data.value.stateVersion}};pending.value=command;busy.value=true;emit('processing',true);error.value='';notice.value='';let done=false;try{const response=await $fetch<any>(base()+command.path,{method:'POST',body:command.body});if(!await refresh())return;pending.value=null;review.value=null;notice.value=response.cancelledOrderId?'Ordem removida. A ação não será confirmada.':'';done=true}catch(e:any){if(e.status>=400&&e.status<500){pending.value=null;review.value=null;await refresh()}error.value=e.data?.message||'Falha de conexão. Repita para recuperar o mesmo comando.'}finally{busy.value=false;emit('processing',!!pending.value)}if(done)emit('changed')}
watch(()=>[props.game.id,props.game.stateVersion],async()=>{review.value=null;await refresh()})
onMounted(async()=>{emit('processing',!!pending.value);await refresh()})

watch(mode,()=>{if(data.value?.stateVersion!==undefined)navigationNews.markRead(props.game.id,'infrastructure.'+mode.value)})
</script>
<template><div class="logistics-panel" :aria-busy="busy" @click.capture="captureAction($event)"><ActionFeedback :target="feedbackTarget" :section="mode" :turn="game.currentTurn" v-model:error="error" v-model:notice="notice" />
 <section v-if="pending&&!busy" class="panel"><p>Comando aguardando confirmação. Repetir não duplica compras ou débitos.</p><button class="primary" @click="run">Repetir comando</button></section>
 <template v-if="data">
 <div class="stats finance-stats logistics-summary"><section class="stat"><span>MANUTENÇÃO SEMANAL</span><strong>{{money(data.headquarters.weeklyMaintenanceCents)}}</strong><small>Fechamento a cada 28 turnos, após salários</small></section><section class="stat"><span>ARMAZENAGEM</span><strong>{{data.load}} / {{data.loadCapacity}}</strong><small>Inclui kits em entrega, serviço e missão</small></section></div>
 <SectionNav :game-id="game.id" scope="infrastructure" v-model="mode" label="Seções de sede e logística" :disabled="locked" :items="[['headquarters','Instalações'],['catalog','Comprar kits'],['inventory','Estoque e serviços']]" />
 <div v-if="data.headquarters.arrearsCents" class="error">Manutenção em atraso: {{money(data.headquarters.arrearsCents)}}. Compras, serviços, melhorias, novas missões e treinos suspensos. A quitação ocorre ao avançar com caixa suficiente após os salários.</div>

 <template v-if="mode==='headquarters'"><div class="section-intro"><h2>{{data.headquarters.name}}</h2><p>Melhorias sequenciais mantêm a capacidade atual até a conclusão. Não há cobrança retroativa anterior ao turno {{data.headquarters.activatedTurn}}.</p></div><div class="personnel-grid"><article v-for="m in data.modules" :key="m.type" data-action-card :id="'logistics-m-'+m.type" class="panel"><span class="eyebrow">NÍVEL {{m.level}} / 5</span><h3>{{m.name}}</h3><p>{{m.capacity}} {{m.capacity===1?({training:'vaga de treinamento',infirmary:'vaga de tratamento',depot:'unidade de armazenagem',operations:'operação simultânea',administration:'operador com vínculo'} as Record<string,string>)[m.type]:capacities[m.type]}}<br>{{money(m.weeklyCostCents)}} / semana</p><section v-if="m.targetLevel" class="facility-progress"><label>Melhoria em andamento <strong>{{Math.max(0,m.dueTurn-data.currentTurn)}} turnos restantes</strong><progress :value="upgradeProgress(m)" :max="m.upgradeTurns" :aria-label="'Melhoria de '+m.name" /></label></section><p v-if="m.level<5" class="facility-benefit">Capacidade: <strong>{{m.capacity}} → {{m.nextCapacity}}</strong><br>Manutenção no próximo nível: {{money(m.nextWeeklyCostCents)}} / semana</p><p v-if="m.targetLevel">Melhoria para nível {{m.targetLevel}} em andamento · conclusão turno {{m.dueTurn}}. Capacidade atual preservada.</p><p v-else-if="m.level<5">Próximo nível: {{money(m.upgradeCostCents)}} · {{m.upgradeTurns}} turnos</p><button v-if="m.level<5&&!m.targetLevel&&!scheduled(m.type).length" class="secondary" :disabled="locked||!!data.headquarters.arrearsCents||game.cashCents<m.upgradeCostCents" @click="prepare('/headquarters/modules/'+m.type+'/upgrade',{},'Melhorar '+m.name,m.upgradeCostCents,'Conclusão em '+m.upgradeTurns+' turnos; capacidade '+m.nextCapacity+'; manutenção do módulo passa a '+money(m.nextWeeklyCostCents)+'/semana.')">Revisar melhoria</button><span v-else-if="m.level===5" class="tag">Nível máximo</span> <PendingOrderNotice :orders="scheduled(m.type)" :disabled="locked" @remove="cancelQueued" /><FocusDialog v-if="review?.path==='/headquarters/modules/'+m.type+'/upgrade'" title="Revisar melhoria" :busy="busy" :error="error" @close="review=null"><section class="inline-action decision-card"><span class="eyebrow">REVISÃO DO COMANDO</span><h2>{{review.label}}</h2><p>Cobrança ao passar o turno: {{money(review.cost)}}<br>{{review.consequence}}</p><div class="personnel-actions"><button class="primary" :disabled="locked||game.cashCents<review.cost" @click="run">Agendar · {{money(review.cost)}}</button><button class="secondary" :disabled="locked" @click="review=null">Voltar</button></div></section></FocusDialog></article></div></template>
 <template v-else-if="mode==='catalog'"><div class="section-intro"><h2>Catálogo de kits</h2><p>Seis categorias, qualidades I–III. Entrega em quatro turnos. Reparos e reposição são separados; consumo em missão não gera nova cobrança.</p><p>Vagas de preparação simultânea: {{data.preparationCapacity}}. Mínimos para envio: condição {{data.minimumCondition}}, suprimentos {{data.minimumSupplies}}.</p></div><label class="personnel-label">Categoria<select v-model="category"><option value="">Todas</option><option v-for="(label,key) in categories" :key="key" :value="key">{{label}}</option></select></label><label class="personnel-label">Quantidade por compra<input v-model.number="quantity" type="number" min="1" max="10"></label>
 <div class="personnel-grid grouped-kits"><article v-for="group in catalogGroups" :key="group.category" class="panel"><h3>Kit {{categories[group.category]}}</h3><div class="kit-quality" role="group" :aria-label="'Qualidade do kit '+categories[group.category]"><button v-for="variant in group.variants" :key="variant.id" class="secondary" :aria-pressed="activeKit(group).id===variant.id" :disabled="locked" @click="selectQuality(group.category,variant.id)"><strong>{{['I','II','III'][variant.quality-1]}}</strong><small>{{money(variant.priceCents)}}</small><small v-if="purchases(variant.id).length">{{purchases(variant.id).length}} agendada(s)</small></button></div><template v-for="c in [activeKit(group)]" :key="c.id"><div data-action-card :id="'logistics-c-'+c.id"><p class="eyebrow">QUALIDADE {{['I','II','III'][c.quality-1]}}</p><p>{{money(c.priceCents)}} por unidade<br>Carga {{c.weight}} · entrega em {{c.deliveryTurns}} turnos</p><button class="secondary" :disabled="locked||!!purchaseIssue(c)" @click="prepare('/equipment/purchases',{catalogId:c.id,quantity},'Comprar '+quantity+' kit(s) '+c.name,c.priceCents*quantity,'Disponíveis em '+c.deliveryTurns+' turnos; carga adicional '+c.weight*quantity+'.')">{{purchases(c.id).length?'Agendar outra compra':'Revisar compra'}}</button><PendingOrderNotice :orders="purchases(c.id)" :disabled="locked" @remove="cancelQueued" /> <FocusDialog v-if="review?.body.catalogId===c.id" title="Revisar compra" :busy="busy" :error="error" @close="review=null"><section class="inline-action decision-card"><span class="eyebrow">REVISÃO DO COMANDO</span><h2>{{review.label}}</h2><p>Cobrança ao passar o turno: {{money(review.cost)}}<br>{{review.consequence}}</p><div class="personnel-actions"><button class="primary" :disabled="locked||game.cashCents<review.cost" @click="run">Agendar · {{money(review.cost)}}</button><button class="secondary" :disabled="locked" @click="review=null">Voltar</button></div></section></FocusDialog><p v-if="purchaseIssue(c)" class="purchase-issue">{{purchaseIssue(c)}}</p></div></template></article></div>
 </template><template v-else><div class="section-intro"><button v-if="!data.inventory.length" class="secondary" @click="mode='catalog'">Comprar kits →</button><p v-if="!data.inventory.length">Estoque vazio. Compre os kits exigidos pelos contratos e aguarde a entrega.</p></div><div class="personnel-grid"><article v-for="k in data.inventory" :key="k.id" data-action-card :id="'logistics-k-'+k.id" class="panel"><StateBadge :status="k.ready?'ready':k.status" :label="k.ready?'Apto para envio':states[k.status]||k.status" /><h3>Kit {{k.name}}</h3><p>Condição {{k.condition}} / 100<br>Suprimentos {{k.supplies}} / 100<br>Carga {{k.weight}}<br><span v-if="k.dueTurn">Disponível em turno {{k.dueTurn}}</span><span v-else-if="k.missionId">Alocado a missão</span><span v-else>{{k.ready?'Apto para envio':'Requer preparação antes do envio'}}</span></p><PendingOrderNotice :orders="scheduled(k.id)" :disabled="locked" @remove="cancelQueued" /><div v-if="k.status==='available'&&!scheduled(k.id).length" class="personnel-actions"><button class="secondary" :disabled="locked||!k.maintenanceCostCents||!!data.headquarters.arrearsCents" @click="prepare('/equipment/'+k.id+'/maintenance',{},'Reparar kit '+k.name,k.maintenanceCostCents,'Condição volta a 100 em quatro turnos. Suprimentos preservados.')">Reparar · {{money(k.maintenanceCostCents)}}</button><button class="secondary" :disabled="locked||!k.resupplyCostCents||!!data.headquarters.arrearsCents" @click="prepare('/equipment/'+k.id+'/resupply',{},'Repor kit '+k.name,k.resupplyCostCents,'Suprimentos voltam a 100 em quatro turnos. Condição preservada.')">Repor · {{money(k.resupplyCostCents)}}</button></div> <FocusDialog v-if="review?.path.startsWith('/equipment/'+k.id+'/')" title="Revisar serviço do kit" :busy="busy" :error="error" @close="review=null"><section class="inline-action decision-card"><span class="eyebrow">REVISÃO DO COMANDO</span><h2>{{review.label}}</h2><p>Cobrança ao passar o turno: {{money(review.cost)}}<br>{{review.consequence}}</p><div class="personnel-actions"><button class="primary" :disabled="locked||game.cashCents<review.cost" @click="run">Agendar · {{money(review.cost)}}</button><button class="secondary" :disabled="locked" @click="review=null">Voltar</button></div></section></FocusDialog></article></div></template>
 </template><p v-else>Carregando infraestrutura…</p></div></template>
